import 'dart:io';
import 'package:downsize/downsize.dart';

void main() async {
  File imageFile = File('path/to/your/image.jpg');
  Uint8List imageData = await imageFile.readAsBytes();
  Uint8List? compressedData = await Downsize.downsize(data: imageData, maxSize: 500, minQuality: 60);
}
